parameters.jsCode:
// Parse Perplexity response và format cho video
const response = $input.item.json;
const content = response.choices[0].message.content;

// Parse content thành ranking array
// Giả sử Perplexity trả về format đã yêu cầu
const rankings = [];
const items = content.split(/\d+\./g).slice(1); // Split by numbers

items.forEach((item, index) => {
  const rankNumber = 10 - index;
  if (rankNumber >= 1) {
    // Extract thông tin từ mỗi item
    const lines = item.trim().split('\n');

    rankings.push({
      voiceoverText: lines[0] || `At number ${rankNumber}...`,
      imagePrompt: lines[1] || 'Beautiful travel destination image',
      lowerThirdText: lines[2] || `Item ${rankNumber}`
    });
  }
});

return {
  rankings: rankings
};

